import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Cpu, History, Sparkles, ShieldCheck } from 'lucide-react';

const Navbar = () => {
  const location = useLocation();

  return (
    <header className="sticky top-0 z-50 glass-card border-b border-scifi-600/20 backdrop-blur-2xl">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16 sm:h-20">

          {/* Minimal Brand Logo */}
          <Link to="/" className="flex items-center space-x-3 group">
            <div className="relative flex items-center justify-center w-10 h-10 rounded-xl bg-gradient-to-br from-scifi-600 via-scifi-700 to-scifi-950 p-[1px] shadow-purple-glow transition-transform duration-300 group-hover:scale-105">
              <div className="w-full h-full bg-scifi-950 rounded-[11px] flex items-center justify-center">
                <Cpu className="w-5 h-5 text-scifi-100 animate-pulse" />
              </div>
            </div>
            <span className="font-heading font-extrabold text-2xl tracking-tight text-scifi-100">
              SkillHive
            </span>
          </Link>

          {/* System Status Badges */}
          <div className="hidden lg:flex items-center space-x-2 px-3 py-1 rounded-full glass-pill border border-scifi-600/40 text-xs font-mono">
            <span className="relative flex h-2 w-2">
              <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-scifi-600 opacity-75"></span>
              <span className="relative inline-flex rounded-full h-2 w-2 bg-scifi-500"></span>
            </span>
            <span className="text-scifi-200 font-medium tracking-wide">System Online</span>
            <span className="text-scifi-700">|</span>
            <span className="text-scifi-100 flex items-center">
              <ShieldCheck className="w-3.5 h-3.5 mr-1 text-scifi-600" /> Trust Core Active
            </span>
          </div>

          {/* Clean Navigation Links */}
          <nav className="flex items-center space-x-2 sm:space-x-4">
            <Link
              to="/"
              className={`flex items-center space-x-2 px-4 py-2 rounded-xl text-xs font-mono font-semibold transition-all duration-200 ${
                location.pathname === '/'
                  ? 'bg-scifi-600/30 text-scifi-100 border border-scifi-600/50 shadow-purple-glow'
                  : 'text-scifi-200 hover:text-scifi-100 hover:bg-white/5'
              }`}
            >
              <Sparkles className="w-3.5 h-3.5 text-scifi-600" />
              <span>Command Center</span>
            </Link>

            <Link
              to="/history"
              className={`flex items-center space-x-2 px-4 py-2 rounded-xl text-xs font-mono font-semibold transition-all duration-200 ${
                location.pathname === '/history'
                  ? 'bg-scifi-600/30 text-scifi-100 border border-scifi-600/50 shadow-purple-glow'
                  : 'text-scifi-200 hover:text-scifi-100 hover:bg-white/5'
              }`}
            >
              <History className="w-3.5 h-3.5 text-scifi-600" />
              <span>Analysis Logs</span>
            </Link>
          </nav>

        </div>
      </div>
    </header>
  );
};

export default Navbar;
